def _stage_and_rotate(parent, plan, blobs, digest, target_paths, baseline_heads):
    # Stage all members first (private sibling directories; no member
    # byte changes), then hold every member lock at once and rotate:
    # this is the family-wide switch point.
    canonical = {}
    for member in plan:
        _stage_one_member(parent, member, blobs, canonical)
        _validate_staging(parent, member, blobs)
    locks = []
    lease_fds = {}
    ordered = sorted(zip(plan, target_paths), key=lambda item: item[1])
    try:
        for member, path in ordered:
            lock = _DirectoryChainLock(path)
            lock.__enter__()
            locks.append((member, path, lock))
            _sync_register(path)
            lease_fds[path] = _acquire_sync_lease(path)
        # A member that moved during staging would make the application
        # lose the appended save: refuse before the first rename, so the
        # target family stays byte for byte as it was.
        for member, path, _lock in ordered:
            store = _DirectoryChainStore(path)
            current_head = _read_head_optional(store)
            if current_head != baseline_heads[path]:
                raise CheckpointError(
                    f"family sync target member {member['name']!r} moved "
                    "while the sync was being applied (a save appended a "
                    "segment); the target family is left untouched -- "
                    "re-run the diff against the current target family"
                )
            # A fold marker must have been waited out by the snapshot;
            # defend regardless.
            if _member_fold_busy(path):
                raise CheckpointError(
                    f"family sync cannot publish while member "
                    f"{member['name']!r} is compacting"
                )
        for member, path, _lock in ordered:
            _rotate_one_member(
                parent, member, baseline_heads[path], digest
            )
    finally:
        for member, path, lock in reversed(locks):
            _sync_release(path)
            _release_sync_lease(lease_fds.get(path))
            lock.__exit__(None, None, None)


