def _resume_or_apply(parent, raw, digest, target_digest, plan, blobs):
    names = [member["name"] for member in plan]
    target_paths = [os.path.join(parent, name) for name in names]
    for path in target_paths:
        if not os.path.isdir(path):
            raise FileNotFoundError(
                f"family sync target member directory not found: {path!r}"
            )
    # First finish any member a killed rotation left mid-switch.
    _finish_mid_rotation_members(parent)
    heads, records, documents = _capture_family(target_paths)
    done, pending = _partition_members(
        plan, blobs, target_paths, heads, records
    )
    if not pending:
        _cleanup_application(parent)
        return None
    pending_paths = [path for _member, path in pending]
    marker = _read_family_marker(parent)
    resuming = marker is not None and marker["d"] == digest
    if not resuming:
        digest_heads = {
            names[i]: heads[path] for i, path in enumerate(target_paths)
        }
        digest_records = {
            names[i]: records[path] for i, path in enumerate(target_paths)
        }
        if _family_digest(names, digest_heads, digest_records) != target_digest:
            raise CheckpointError(
                "family sync artifact does not match the target family: the "
                "target family has changed since the diff was produced (its "
                "member-reachable state differs from the digest recorded in "
                "the artifact)"
            )
        # Whole-artifact validation against the target before one byte
        # of any member changes.
        _validate_against_target(
            plan, blobs, target_paths, heads, records, documents
        )
        _write_application_files(parent, digest, raw)
    # Build the new chains for the pending members in private staging
    # directories (a failure here changes no member byte; the debris and
    # the application files are dropped so the rejected attempt leaves
    # no resumable marker).
    try:
        canonical = _stage_pending_members(parent, done, pending, blobs)
        _rotate_members(parent, pending, digest, heads, canonical)
    except BaseException:
        if not _read_family_marker(parent):
            raise
        member_mid_switch = any(
            _read_member_marker(path) is not None for _m, path in pending
        )
        if not member_mid_switch:
            _abort_application(parent, plan)
        raise
    _cleanup_application(parent)


def _partition_members(plan, blobs, target_paths, heads, records):
    """Split members into already-finished and still-pending for an apply."""
    done = []
    pending = []
    for member, path in zip(plan, target_paths):
        member_records = records[path]
        if heads[path] == member["head"] and all(
            member_records[_segment_name(slot)][0]
            == _raw_at(member_records, member, slot, blobs)
            for slot in range(member["head"] + 1)
        ):
            done.append((member, path))
        else:
            pending.append((member, path))
    return done, pending


def _stage_pending_members(parent, done, pending, blobs):
    """Populate and validate staging chains for the pending members.

    Returns the canonical slot map: carried blocks map block id -> the
    first staging file holding them and shared slots map the live
    file's inode -> the first staging file, so both kinds stay one
    physical copy across members.
    """
    canonical_blocks = {}
    canonical_inodes = {}
    for member, path in done:
        for slot, block_id in member["carried"].items():
            canonical_blocks.setdefault(
                block_id, os.path.join(path, _segment_name(slot))
            )
        for slot in member["shared"]:
            slot_path = os.path.join(path, _segment_name(slot))
            try:
                stat = os.stat(slot_path)
            except OSError:
                continue
            canonical_inodes.setdefault((stat.st_dev, stat.st_ino), slot_path)
    for member, path in pending:
        _stage_one_member(
            parent, member, path, blobs, canonical_blocks, canonical_inodes
        )
        _validate_staging(parent, member)
    return canonical_blocks


def _abort_application(parent, plan):
    for member in plan:
        _remove_tree_quietly(_staging_dir(parent, member["name"]))
    marker = _read_family_marker(parent)
    if marker is not None:
        _unlink_quietly(_family_artifact_path(parent, marker["d"]))
    _unlink_quietly(_family_marker_path(parent))
    _fsync_directory(parent)


def _write_application_files(parent, digest, raw):
    artifact_path = _family_artifact_path(parent, digest)
    if not os.path.exists(artifact_path):
        _atomic_write(parent, os.path.basename(artifact_path), raw)
    _atomic_write(parent, SYNC_MARKER_NAME, _encode_family_marker(digest))
    _fsync_directory(parent)


def _rotate_members(parent, pending, digest, baseline_heads, canonical):
    """Hold every pending member's lock and rotate them, one after another.

    The locks are all taken (sorted) before any rename: a member whose
    head moved during staging rejects the whole switch first, so either
    every pending member rotates or none does.  Each member's own
    rotation is itself crash-resumable via its member marker.
    """
    ordered = sorted(pending, key=lambda item: item[1])
    locks = []
    lease_fds = {}
    try:
        for member, path in ordered:
            lock = _DirectoryChainLock(path)
            lock.__enter__()
            locks.append((member, path, lock))
            _sync_register(path)
            lease_fds[path] = _acquire_sync_lease(path)
        for member, path, _lock in ordered:
            store = _DirectoryChainStore(path)
            current_head = _read_head_optional(store)
            if current_head != baseline_heads[path]:
                raise CheckpointError(
                    f"family sync target member {member['name']!r} moved "
                    "while the sync was being applied (a save appended a "
                    "segment); the target family is left untouched -- re-run "
                    "the diff against the current target family"
                )
            if _member_fold_busy(path):
                raise CheckpointError(
                    f"family sync cannot publish while member "
                    f"{member['name']!r} is compacting"
                )
        for member, path, _lock in ordered:
            _rotate_one_member(parent, member, baseline_heads[path], digest)
    finally:
        for member, path, lock in reversed(locks):
            _sync_release(path)
            _release_sync_lease(lease_fds.get(path))
            lock.__exit__(None, None, None)


