def _verify_imported_member(final, member, blobs):
    """Check an already-present member against the import plan on resume.

    A member left by the interrupted import of the same artifact holds
    exactly the planned prefix segments and a head at or beyond the plan
    (a live training process may have appended since).  Anything else
    means the location holds a different chain, and the whole import is
    rejected before another byte is written.
    """
    what = f"family import target member {final!r}"
    if not os.path.isdir(final):
        raise CheckpointError(f"{what} is not a chain directory")
    try:
        with open(os.path.join(final, _HEAD_NAME), "rb") as fh:
            head_raw = fh.read()
    except FileNotFoundError:
        raise CheckpointError(f"{what} has no head pointer") from None
    try:
        text = head_raw.decode("ascii")
        if not re.fullmatch(r"\d+", text):
            raise ValueError
        actual_head = int(text)
    except (UnicodeDecodeError, ValueError):
        raise CheckpointError(f"{what} has a corrupt head pointer") from None
    if actual_head < member["head"]:
        raise CheckpointError(
            f"{what} does not match the family artifact (its head "
            f"{actual_head} is below {member['head']})"
        )
    for slot, block_id in enumerate(member["segments"]):

        walker.apply_delta(slot, _raw_at(records, member, slot, blobs))
    return walker.document()


def _family_matches_end_state(plan, blobs, target_paths, heads, records):
    for member, path in zip(plan, target_paths):
        if heads[path] != member["head"]:
            return False
        member_records = records[path]
        for slot in range(member["head"] + 1):
            name = _segment_name(slot)
            if member_records[name][0] != _raw_at(member_records, member, slot, blobs):
                return False
    return True


def _validate_against_target(plan, blobs, target_paths, heads, records, documents):
    """Pre-write validation: shared slots resolve and chains walk/agree."""
    assembled = []
    for member, path in zip(plan, target_paths):
        target_head = heads[path]
        member_records = records[path]
        for slot in member["shared"]:
            if slot > target_head:
                raise CheckpointError(
                    f"family sync artifact member {member['name']!r} marks "
                    f"segment {slot} shared but the target member's head is "
                    f"{target_head}"
                )
            if _segment_name(slot) not in member_records:
                raise CheckpointError(
                    f"family sync target member {member['name']!r} is "
                    f"missing the shared segment {_segment_name(slot)}"
                )
        assembled.append(_walk_member(member, blobs, member_records))
    _check_family_shape_agreement(
        assembled + [documents[path] for path in target_paths],
        [member["name"] for member in plan]
        + [f"target:{member['name']}" for member in plan],
        "family sync",
    )


